perl -e '
my @entities = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation
  MemoShare Reaction User UserIdentity UserSetting
);

# also consider proto store types? stick to store.* types first

# collect go files outside store layer (store/, store/db, store/cache, store/test, store/seed, store/migration)
open P, "find /bench/repo -name \"*.go\" ! -path \"*/.git/*\" ! -path \"*/proto/gen/*\" |" or die $!;
my @files;
while (<P>) {
  chomp;
  next if m{^/bench/repo/store(/|$)};
  push @files, $_;
}

# package = directory
sub pkg {
  my $f = shift;
  $f =~ s{/[^/]+$}{};
  $f =~ s{^/bench/repo/}{};
  return $f;
}

my %counts; # entity -> {pkg -> count}
my %files;  # entity -> {pkg -> [files]}

for my $f (@files) {
  open my $fh, "<", $f or next;
  local $/;
  my $c = <$fh>;
  my $p = pkg($f);
  for my $e (@entities) {
    # match store.Type as a type/value reference, not as substring of another ident
    if ($c =~ /\bstore\.\Q$e\E\b/) {
      $counts{$e}{$p}++;
      push @{$files{$e}{$p}}, $f;
    }
  }
}

print "Entity type references from packages outside store/:\n";
for my $e (sort { scalar(keys %{$counts{$b}}) <=> scalar(keys %{$counts{$a}}) || $a cmp $b } @entities) {
  my $n = scalar keys %{$counts{$e}||{}};
  printf "%2d pkgs  %-20s  %s\n", $n, $e, join(", ", sort keys %{$counts{$e}||{}});
}
'

